mapper.select:
SELECT channel_id AS `key`, AVG(ratio) AS `value` FROM (SELECT channel_id, data_size / LAG(data_size) OVER (PARTITION BY channel_id) AS ratio FROM alt_monitoring_data WHERE 1 = 1
AND client_id = #{model.clientId}
AND data_type = #{model.dataType}
) vid GROUP BY channel_id HAVING AVG(ratio) IS NOT NULL ORDER BY channel_id

SELECT channel_id AS `key`,AVG(data_size) AS `value` FROM alt_monitoring_data WHERE 1 = 1
AND client_id = #{model.clientId}
AND data_type = #{model.dataType}
GROUP BY channel_id HAVING AVG(data_size) IS NOT NULL ORDER BY channel_id

select this.channel_id as `channelId`, today_nlpData, today_metaData, his_diff_nlpData_avg, alarm_ompare, ompare_rise, ompare_reduce, /** （计算公式=（今日NLP返回声音数/今日原始数据数量-历史比值均值）/历史比值均值*100%） **/ IFNULL(round(((ifnull(today_nlpData, 0) / ifnull(today_metaData, 0) - his_diff_nlpData_avg) / his_diff_nlpData_avg) * 100, 2), 0) as `statistics`, IF( ompare_rise >= IFNULL(round(((ifnull(today_nlpData, 0) / ifnull(today_metaData, 0) - his_diff_nlpData_avg) / his_diff_nlpData_avg) * 100, 2), 0) and IFNULL(round(((ifnull(today_nlpData, 0) / ifnull(today_metaData, 0) - his_diff_nlpData_avg) / his_diff_nlpData_avg) * 100, 2), 0) >= ompare_reduce, 0,1 ) AS threshold from ( ) as this left join ( ) as diff_his on this.client_id = diff_his.client_id and this.channel_id = diff_his.channel_id left join ( select client_id,channel_id,alarm_ompare,ompare_rise,ompare_reduce from voc.alt_task_config_data where data_type = 'nlpData' ) task on this.client_id = task.client_id and this.channel_id = task.channel_id where 1 = 1
AND this.client_id = #{model.clientId}
order by this.channel_id

/** 推送任务最后一次抓取时间 **/ WITH task_last_exc AS ( SELECT max(stop_time) AS last_exec_time, min(start_time) AS start_exec_time, /** stop_time, **/ /** start_time,**/ task.client_id, task.channel_id, task.data_type, task.scheduled_time FROM alt_task_config_data task LEFT JOIN alt_task_execution_record record on task.id = record.task_id AND task.client_id = record.client_id AND task.channel_id = record.channel_id AND record.data_type = 'pushData' AND record.status = '1' AND CASE task.period WHEN 'day' THEN to_date(stop_time) = to_date(#{model.createTime}) and to_date(start_time) = to_date(#{model.createTime}) WHEN 'last_7_days' THEN (stop_time >= DATE(#{model.createTime}) - INTERVAL 7 DAY) and (start_time >= DATE(#{model.createTime}) - INTERVAL 7 DAY) ELSE 1 = 1 END where 1 = 1 AND task.data_type = 'pushData'
AND task.client_id = #{model.clientId}
group by task.client_id , task.channel_id, task.data_type, task.scheduled_time)
SELECT channel_id, data_type, last_exec_time, IFNULL(ROUND(TIME_TO_SEC(date_format(IFNULL(last_exec_time, #{model.createTime}),'%H:%i:%S')) / 3600 - TIME_TO_SEC(IF(IFNULL(ROUND(TIME_TO_SEC(date_format(IFNULL(last_exec_time, #{model.createTime}),'%H:%i:%S')) / 3600 - TIME_TO_SEC(date_format(scheduled_time,'%H:%i:%S')) / 3600), 0) >= 0, date_format(scheduled_time,'%H:%i:%S'), date_format(start_exec_time,'%H:%i:%S')) ) / 3600), 0) AS `statistics`, IF(IFNULL(ROUND(TIME_TO_SEC(date_format(IFNULL(last_exec_time, #{model.createTime}),'%H:%i:%S')) / 3600 - TIME_TO_SEC(date_format(scheduled_time,'%H:%i:%S')) / 3600), 0) >= 0, 1, 0) AS `threshold` FROM task_last_exc AS tle where 1 = 1
AND tle.client_id = #{model.clientId}
order by channel_id

select this.channel_id as `channelId`, today_metaData, his_metaData_avg, alarm_ompare, ompare_rise, ompare_reduce, /** （计算公式=（今日推送量-历史均值）/历史均值*100%） **/ ROUND(((today_metaData - his_metaData_avg) / his_metaData_avg) * 100,2) as `statistics`, IF( ompare_rise >= ROUND(((today_metaData - his_metaData_avg) / his_metaData_avg) * 100,2) and ROUND(((today_metaData - his_metaData_avg) / his_metaData_avg) * 100,2) >= ompare_reduce, 0,1 ) AS threshold from ( ) as this left join ( ) as h on this.client_id = h.client_id and this.channel_id = h.channel_id left join ( select client_id,channel_id,alarm_ompare,ompare_rise,ompare_reduce from voc.alt_task_config_data where data_type = 'metaData' ) task on this.client_id = task.client_id and this.channel_id = task.channel_id where 1 = 1
AND this.client_id = #{model.clientId}
order by this.channel_id
